from decimal import Decimal, ROUND_HALF_UP


class Money:
    def __init__(self, amount):
        self.amount = Decimal(str(amount))

    def __add__(self, other):
        return Money(self.amount + other.amount)

    def __mul__(self, qty):
        return Money(self.amount * Decimal(str(qty)))

    def __eq__(self, other):
        return self.amount == other.amount

    def __repr__(self):
        return f"Money({self.amount:.2f})"

    def cents(self):
        # Convert to cents exactly. Since we use Decimal, 1.15 is exactly 1.15.
        # Multiplying by 100 gives 115.00. Converting to int gives 115.
        return int((self.amount * 100).to_integral_value(rounding=ROUND_HALF_UP))

